-- ── Categories ─────────────────────────────────────────────────────────────
insert into public.categories (id, slug, name, tagline, description, icon, sort_order, is_active) values
  ('cat-ig-usernames', 'instagram-usernames', 'يوزرات إنستقرام', 'رباعية • نادرة • مميزة', 'أكبر تشكيلة يوزرات إنستقرام رباعية ومميزة — شبه ثلاثية، مكررة، شبه أرقام، وأحرف كاملة. نقل ملكية آمن وموثّق خطوة بخطوة.', 'AtSign', 1, true),
  ('cat-ig-services', 'instagram-services', 'خدمات إنستقرام', 'نقل يوزر • زيادة متابعين', 'نقل اليوزر من حساب لحساب بأمان تام، وزيادة متابعين بجودة عالية وضمان تعويض النقص.', 'TrendingUp', 2, true),
  ('cat-snap-usernames', 'snapchat-usernames', 'يوزرات سناب شات', 'أسماء قصيرة ومميزة', 'بيع يوزرات سناب شات مميزة بأطوال وفئات مختلفة، مع نقل ملكية مباشر وضمان بعد التسليم.', 'Ghost', 3, true),
  ('cat-tiktok-usernames', 'tiktok-usernames', 'يوزرات تيك توك', 'احجز اسمك قبل غيرك', 'بيع يوزرات تيك توك قصيرة ومميزة وأسماء علامات تجارية، مع نقل آمن وتوثيق كامل للعملية.', 'Music2', 4, true),
  ('cat-accounts', 'accounts', 'حسابات سوشيال ميديا', 'حسابات جاهزة بمتابعين', 'حسابات إنستقرام وتيك توك وسناب شات جاهزة بمتابعين وتفاعل حقيقي — ابدأ من نقطة متقدمة بدل الصفر.', 'Users', 5, true),
  ('cat-sawa', 'sawa', 'باقات سوا', 'بيع وشحن فوري', 'بيع وشحن باقات سوا (SAWA) بكل الفئات، تفعيل مباشر على رقمك خلال دقائق من تأكيد الطلب.', 'Signal', 6, true),
  ('cat-plus-apps', 'plus-apps', 'تطبيقات بلس', 'نسخ معدّلة بمزايا إضافية', 'توفير تطبيقات Plus المعدّلة بمزايا ما بتلاقيها بالنسخ العادية، مع شرح التركيب ومتابعة التحديثات.', 'Smartphone', 7, true)
on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  tagline = excluded.tagline,
  description = excluded.description,
  icon = excluded.icon,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

-- ── Services ───────────────────────────────────────────────────────────────
insert into public.services (id, category_slug, slug, title, summary, description, price, old_price, currency, unit, delivery_time, features, badge, is_featured, is_active, sort_order) values
  ('svc-ig-user-premium', 'instagram-usernames', 'instagram-username-premium', 'يوزرات إنستقرام مميزة', 'أسماء نادرة وقوية ترفع قيمة حسابك من أول نظرة.', 'تشكيلة يوزرات إنستقرام مميزة — كلمات إنجليزية معروفة، أسماء أشخاص، وأسماء علامات تجارية. الأسعار تختلف حسب قوة الاسم والطلب عليه، وبنرسلك القائمة المتاحة حالياً على الواتساب مع صور توثّق كل يوزر قبل الشراء.', 350, 480, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["قائمة متجددة يومياً على الواتساب","نقل ملكية آمن بالكامل","ضمان عدم الاسترجاع بعد التسليم","وسيط ضمان متاح عند الطلب"]'::jsonb, 'الأكثر طلباً', true, true, 1),
  ('svc-ig-user-4', 'instagram-usernames', 'instagram-username-4-char', 'يوزرات إنستقرام رباعية', 'أربعة خانات فقط — الفئة اللي كل حدا بدوّر عليها.', 'يوزرات إنستقرام من أربع خانات، أقصر وأنظف شكل متاح للحسابات الجديدة والقديمة. متوفرة بتشكيلات مختلفة (أحرف، أرقام، خليط) وبأسعار تناسب كل ميزانية.', 180, 250, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["أربع خانات فقط","تشكيلات وأسعار متعددة","شرح مباشر لكل خطوة نقل","ضمان كامل بعد التسليم"]'::jsonb, NULL, true, true, 2),
  ('svc-ig-user-4-like-3', 'instagram-usernames', 'instagram-username-4-like-3', 'يوزرات رباعية شبه ثلاثية', 'بتبان ثلاثية للعين — أقرب شي للثلاثي بسعر الرباعي.', 'يوزرات رباعية بس شكلها بيوحي إنها ثلاثية، لأن أحد أحرفها رفيع أو مدموج بصرياً مع اللي جنبه (مثل l و i و j). خيار ذكي لمن بده مظهر اليوزر الثلاثي النادر بجزء بسيط من سعره.', 420, 600, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["مظهر ثلاثي بسعر رباعي","فئة نادرة وكمية محدودة","معاينة الشكل قبل الشراء","نقل ملكية موثّق"]'::jsonb, 'نادر', true, true, 3),
  ('svc-ig-user-4-repeat', 'instagram-usernames', 'instagram-username-4-repeated', 'يوزرات رباعية مكررة', 'حروف متكررة سهلة الحفظ زي aabb و xxxy.', 'يوزرات رباعية بأحرف متكررة (aaaa، aabb، abab، xxxy وغيرها). سهلة الحفظ والكتابة وبتعطي الحساب طابع مميز، وهي من الفئات المطلوبة كتير للمتاجر ومنشئي المحتوى.', 260, 340, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["أنماط تكرار متعددة","سهلة الحفظ والكتابة","مطلوبة للمتاجر ومنشئي المحتوى","ضمان بعد التسليم"]'::jsonb, NULL, false, true, 4),
  ('svc-ig-user-4-numeric-look', 'instagram-usernames', 'instagram-username-4-numeric-look', 'يوزرات رباعية شبه أرقام', 'أحرف بتنقرأ كأرقام — شكل نظيف ومختلف.', 'يوزرات رباعية بتستخدم أحرف بتشبه الأرقام بصرياً (o بدل 0، l بدل 1، s بدل 5، b بدل 6). بتعطي إحساس اليوزر الرقمي النادر مع بقاء الاسم أحرف بالكامل.', 230, NULL, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["شكل رقمي بأحرف كاملة","خيارات متعددة متاحة","معاينة قبل الشراء","نقل آمن وموثّق"]'::jsonb, NULL, false, true, 5),
  ('svc-ig-user-4-letters', 'instagram-usernames', 'instagram-username-4-letters', 'يوزرات رباعية أحرف', 'أحرف صافية بدون أرقام ولا شرطات — الأنظف شكلاً.', 'يوزرات رباعية من أحرف إنجليزية فقط، بدون أي أرقام أو شرطة سفلية. هي الفئة الأنظف والأغلى ضمن الرباعيات لأنها الأقرب لشكل الاسم الحقيقي أو الكلمة المفهومة.', 300, 400, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["أحرف فقط — بدون أرقام أو _","الأنظف شكلاً بين الرباعيات","بعضها كلمات مفهومة","ضمان عدم الاسترجاع"]'::jsonb, NULL, false, true, 6),
  ('svc-ig-transfer', 'instagram-services', 'instagram-username-transfer', 'نقل يوزرات إنستقرام', 'ننقل اليوزر من حسابك القديم للجديد بدون ما يضيع.', 'عندك يوزر بحساب وبدك تنقله لحساب تاني بدون ما حدا يخطفه بالثانية اللي بينهم؟ منتولى العملية كاملة بالتوقيت الصحيح والطريقة الآمنة، مع تأكيد لك بكل خطوة قبل تنفيذها.', 90, NULL, '₪', 'للعملية', 'التنفيذ خلال 1-2 ساعة', '["توقيت دقيق يمنع خطف اليوزر","تأكيد منك قبل كل خطوة","يعمل بين حساباتك الشخصية","لا تدفع إلا بعد نجاح النقل"]'::jsonb, 'مضمون', true, true, 1),
  ('svc-ig-followers', 'instagram-services', 'instagram-followers', 'زيادة متابعين إنستقرام', 'متابعين بجودة عالية مع ضمان تعويض النقص ٣٠ يوم.', 'زيادة متابعين إنستقرام بحسابات نشطة وبسرعة إضافة طبيعية تحمي حسابك من أي إنذار. ما بنطلب كلمة المرور نهائياً — بس اليوزر والحساب لازم يكون عام أثناء التنفيذ.', 15, 22, '₪', 'لكل 1000', 'يبدأ خلال 5 دقائق', '["بدون كلمة مرور — اليوزر فقط","ضمان تعويض النقص 30 يوم","سرعة إضافة آمنة ومتدرجة","متاح لأي عدد"]'::jsonb, NULL, true, true, 2),
  ('svc-snap-usernames', 'snapchat-usernames', 'snapchat-usernames', 'بيع يوزرات سناب شات', 'يوزرات سناب قصيرة ومميزة بأسعار تنافسية.', 'تشكيلة يوزرات سناب شات مميزة بأطوال وفئات مختلفة — رباعية، خماسية، وأسماء نادرة. بنرسلك المتاح حالياً على الواتساب مع الأسعار، وبتختار براحتك قبل ما تدفع إشي.', 120, 170, '₪', 'تبدأ من', 'تسليم خلال 1-3 ساعات', '["فئات وأطوال متعددة","نقل ملكية مباشر","قائمة متجددة على الواتساب","ضمان بعد التسليم"]'::jsonb, NULL, true, true, 1),
  ('svc-tiktok-usernames', 'tiktok-usernames', 'tiktok-usernames', 'بيع يوزرات تيك توك', 'احجز اسم علامتك على تيك توك قبل ما حدا ياخده.', 'يوزرات تيك توك قصيرة ومميزة وأسماء علامات تجارية محجوزة. مثالية لمن بده اسم موحّد على كل المنصات، أو بده يبدأ حساب باسم قوي من أول يوم.', 140, NULL, '₪', 'تبدأ من', 'تسليم خلال 2-5 ساعات', '["أسماء قصيرة وعلامات تجارية","توحيد اسمك على كل المنصات","نقل آمن وموثّق","خدمة البحث عن يوزر محدد"]'::jsonb, NULL, true, true, 1),
  ('svc-acc-instagram', 'accounts', 'instagram-accounts', 'حسابات إنستقرام', 'حسابات جاهزة بمتابعين وتفاعل — ابدأ من نقطة متقدمة.', 'حسابات إنستقرام جاهزة بأعداد متابعين مختلفة وتفاعل حقيقي، مناسبة للمتاجر ومنشئي المحتوى اللي مش بدهم يبلشوا من الصفر. بنوضحلك إحصائيات كل حساب قبل الشراء.', 250, NULL, '₪', 'تبدأ من', 'تسليم خلال 2-6 ساعات', '["إحصائيات كاملة قبل الشراء","أعداد متابعين متنوعة","تسليم بيانات كاملة","ضمان عدم الاسترجاع"]'::jsonb, NULL, false, true, 1),
  ('svc-acc-tiktok', 'accounts', 'tiktok-accounts', 'حسابات تيك توك', 'حسابات بمتابعين ومشاهدات جاهزة للانطلاق.', 'حسابات تيك توك بأعداد متابعين ومشاهدات مختلفة، بعضها وصل لشروط البث المباشر. خيار سريع لمن بده حساب فعّال من أول يوم بدل شهور بناء.', 220, NULL, '₪', 'تبدأ من', 'تسليم خلال 2-6 ساعات', '["بعضها مؤهل للبث المباشر","إحصائيات واضحة قبل الشراء","تسليم بيانات كاملة","ضمان بعد التسليم"]'::jsonb, NULL, false, true, 2),
  ('svc-acc-snapchat', 'accounts', 'snapchat-accounts', 'حسابات سناب شات', 'حسابات سناب بمتابعين ونسبة مشاهدة ستوري عالية.', 'حسابات سناب شات جاهزة بأعداد متابعين مختلفة ونسبة مشاهدة ستوري جيدة، مناسبة للمتاجر اللي بدها تبدأ التسويق على سناب مباشرة.', 280, NULL, '₪', 'تبدأ من', 'تسليم خلال 2-6 ساعات', '["نسبة مشاهدة ستوري جيدة","أعداد متابعين متنوعة","تسليم بيانات كاملة","ضمان بعد التسليم"]'::jsonb, NULL, false, true, 3),
  ('svc-sawa', 'sawa', 'sawa-packages', 'بيع وشحن باقات سوا', 'كل باقات سوا بتفعيل مباشر على رقمك خلال دقائق.', 'بيع وشحن باقات سوا (SAWA) بكل الفئات المتاحة — إنترنت، مكالمات، وباقات مدمجة. أرسل رقمك والباقة اللي بدك إياها وبنفعّلها لك مباشرة، وبنساعدك تختار الأنسب لاستخدامك إذا كنت متردد.', 55, 70, '₪', 'تبدأ من', 'تفعيل خلال 10 دقائق', '["كل الفئات متوفرة","تفعيل مباشر على رقمك","استشارة مجانية لاختيار الباقة","تذكير قبل انتهاء الباقة"]'::jsonb, 'تفعيل فوري', true, true, 1),
  ('svc-plus-apps', 'plus-apps', 'plus-apps', 'توفير تطبيقات Plus المعدّلة', 'نسخ معدّلة بمزايا إضافية مش موجودة بالنسخة العادية.', 'توفير تطبيقات Plus المعدّلة بمزايا زيادة عن النسخ الرسمية. بنوفرلك النسخة المناسبة لجهازك مع شرح خطوات التركيب، وبنعلمك لما ينزل تحديث جديد.', 35, NULL, '₪', 'للتطبيق', 'تسليم خلال 30 دقيقة', '["نسخة مناسبة لجهازك","شرح خطوات التركيب","تنبيه عند نزول تحديث","دعم في حال واجهت مشكلة"]'::jsonb, NULL, false, true, 1)
on conflict (id) do update set
  category_slug = excluded.category_slug,
  slug = excluded.slug,
  title = excluded.title,
  summary = excluded.summary,
  description = excluded.description,
  price = excluded.price,
  old_price = excluded.old_price,
  currency = excluded.currency,
  unit = excluded.unit,
  delivery_time = excluded.delivery_time,
  features = excluded.features,
  badge = excluded.badge,
  is_featured = excluded.is_featured,
  is_active = excluded.is_active,
  sort_order = excluded.sort_order;

-- ── Testimonials ───────────────────────────────────────────────────────────
insert into public.testimonials (id, name, handle, rating, body, is_active, sort_order) values
  ('t1', 'محمود أبو ندى', 'صاحب متجر ملابس', 5, 'أخذت يوزر رباعي أحرف للمتجر وكانت العملية مرتبة وواضحة من أولها لآخرها. شرحولي كل خطوة قبل ما ينفذوها.', true, 1),
  ('t2', 'سُلاف حرب', 'منشئة محتوى', 5, 'كنت خايفة أنقل اليوزر لحالي عشان ما ينخطف. نقلوه بدقيقة وكل إشي تمام. ما توقعت يكون بهالسهولة.', true, 2),
  ('t3', 'أحمد ياسين', 'لاعب ومنشئ محتوى', 5, 'شحنت باقة سوا كذا مرة من عندهم. أرخص من غيرهم والتفعيل بيجي قبل ما أسكّر المحادثة.', true, 3),
  ('t4', 'رنا الأغا', 'صاحبة مشروع حلويات', 5, 'اشتريت حساب إنستقرام جاهز بمتابعين، وبعتولي الإحصائيات كاملة قبل ما أدفع شيكل واحد. ثقة من أول تعامل.', true, 4),
  ('t5', 'كريم دولة', 'صاحب متجر إلكتروني', 5, 'أفضل شي فيهم إنهم بيردوا بسرعة على الواتساب. سألت عشرين سؤال قبل ما أطلب يوزر وما زهقوا ولا مرة.', true, 5),
  ('t6', 'ليان مقداد', 'طالبة جامعية', 5, 'طلبت يوزر رباعي شبه ثلاثي وما كنت مصدقة الشكل. الناس بتحسبه ثلاثي فعلاً وسعره كان بمتناول إيدي.', true, 6)
on conflict (id) do update set
  name = excluded.name,
  handle = excluded.handle,
  rating = excluded.rating,
  body = excluded.body,
  is_active = excluded.is_active,
  sort_order = excluded.sort_order;
